/*
 * export.c - headless evidence run (PNG screenshots + WAV audio).
 *
 * This drives the very same emulator core as the interactive frontends
 * (gba_run_frame renders into ppu.frame with ppu.c, the APU produces the
 * same 44.1 kHz stereo stream that SDL/waveOut consume).  It exists so a
 * change can be demonstrated with artefacts generated by the shipped code
 * rather than by a separate harness.  No SDL, no window, no audio device.
 *
 * PNG is written with stored (uncompressed) deflate blocks so there is no
 * dependency on zlib; WAV is plain 16-bit PCM.
 */
#include "export.h"
#include "gba.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ---------------------------------------------------------------- PNG ---- */
static uint32_t crc_table[256];
static int crc_ready = 0;

static void crc_init(void) {
    for (uint32_t n = 0; n < 256; n++) {
        uint32_t c = n;
        for (int k = 0; k < 8; k++) c = (c & 1) ? 0xEDB88320u ^ (c >> 1) : c >> 1;
        crc_table[n] = c;
    }
    crc_ready = 1;
}

static uint32_t crc_update(uint32_t c, const uint8_t *buf, size_t n) {
    for (size_t i = 0; i < n; i++) c = crc_table[(c ^ buf[i]) & 0xFF] ^ (c >> 8);
    return c;
}

static void be32(FILE *f, uint32_t v) {
    uint8_t b[4] = { (uint8_t)(v >> 24), (uint8_t)(v >> 16), (uint8_t)(v >> 8), (uint8_t)v };
    fwrite(b, 1, 4, f);
}

static void chunk(FILE *f, const char *type, const uint8_t *data, uint32_t len) {
    be32(f, len);
    uint32_t c = crc_update(0xFFFFFFFFu, (const uint8_t *)type, 4);
    if (len) c = crc_update(c, data, len);
    fwrite(type, 1, 4, f);
    if (len) fwrite(data, 1, len, f);
    be32(f, c ^ 0xFFFFFFFFu);
}

/* Adlersum over the raw (unfiltered) scanline stream. */
static uint32_t adler32(const uint8_t *buf, size_t n) {
    uint32_t a = 1, b = 0;
    for (size_t i = 0; i < n; i++) { a = (a + buf[i]) % 65521; b = (b + a) % 65521; }
    return (b << 16) | a;
}

static int write_png(const char *path, const uint16_t *frame) {
    if (!crc_ready) crc_init();

    /* RGB888, one filter byte (0 = none) per row. */
    const uint32_t W = SCREEN_W, H = SCREEN_H;
    size_t raw_len = (size_t)H * (1 + W * 3);
    uint8_t *raw = malloc(raw_len);
    if (!raw) return -1;
    for (uint32_t y = 0; y < H; y++) {
        uint8_t *row = raw + (size_t)y * (1 + W * 3);
        row[0] = 0;
        for (uint32_t x = 0; x < W; x++) {
            uint16_t c = frame[y * W + x];
            uint8_t r = (uint8_t)((c & 0x1F) << 3), g = (uint8_t)(((c >> 5) & 0x1F) << 3), b = (uint8_t)(((c >> 10) & 0x1F) << 3);
            row[1 + x * 3 + 0] = (uint8_t)(r | (r >> 5));
            row[1 + x * 3 + 1] = (uint8_t)(g | (g >> 5));
            row[1 + x * 3 + 2] = (uint8_t)(b | (b >> 5));
        }
    }

    /* zlib stream: 0x78 0x01 header, stored deflate blocks, Adler-32. */
    size_t zlen = 2 + ((raw_len + 65534) / 65535) * 5 + raw_len + 4;
    uint8_t *z = malloc(zlen);
    if (!z) { free(raw); return -1; }
    size_t zpos = 0;
    z[zpos++] = 0x78; z[zpos++] = 0x01;
    size_t off = 0;
    while (off < raw_len) {
        size_t blk = raw_len - off; if (blk > 65535) blk = 65535;
        int final = (off + blk >= raw_len);
        z[zpos++] = (uint8_t)(final ? 1 : 0);
        z[zpos++] = (uint8_t)(blk & 0xFF);
        z[zpos++] = (uint8_t)((blk >> 8) & 0xFF);
        z[zpos++] = (uint8_t)(~blk & 0xFF);
        z[zpos++] = (uint8_t)((~blk >> 8) & 0xFF);
        memcpy(z + zpos, raw + off, blk);
        zpos += blk; off += blk;
    }
    uint32_t ad = adler32(raw, raw_len);
    z[zpos++] = (uint8_t)(ad >> 24); z[zpos++] = (uint8_t)(ad >> 16);
    z[zpos++] = (uint8_t)(ad >> 8);  z[zpos++] = (uint8_t)ad;

    FILE *f = fopen(path, "wb");
    if (!f) { free(raw); free(z); return -1; }
    static const uint8_t sig[8] = { 137, 80, 78, 71, 13, 10, 26, 10 };
    fwrite(sig, 1, 8, f);
    uint8_t ihdr[13];
    ihdr[0] = W >> 24; ihdr[1] = W >> 16; ihdr[2] = W >> 8; ihdr[3] = W;
    ihdr[4] = H >> 24; ihdr[5] = H >> 16; ihdr[6] = H >> 8; ihdr[7] = H;
    ihdr[8] = 8; ihdr[9] = 2; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;  /* 8-bit RGB */
    chunk(f, "IHDR", ihdr, 13);
    chunk(f, "IDAT", z, (uint32_t)zpos);
    chunk(f, "IEND", NULL, 0);
    fclose(f);
    free(raw); free(z);
    return 0;
}

/* ---------------------------------------------------------------- WAV ---- */
static void wav_header(FILE *f, uint32_t data_bytes) {
    uint32_t rate = SAMPLE_RATE;
    uint32_t byte_rate = rate * 2 * 2;
    fwrite("RIFF", 1, 4, f);
    uint32_t chunk_size = 36 + data_bytes;
    fputc(chunk_size & 0xFF, f); fputc((chunk_size >> 8) & 0xFF, f);
    fputc((chunk_size >> 16) & 0xFF, f); fputc((chunk_size >> 24) & 0xFF, f);
    fwrite("WAVEfmt ", 1, 8, f);
    uint32_t fmt = 16; fwrite(&fmt, 4, 1, f);
    uint16_t pcm = 1, ch = 2, bits = 16;
    uint16_t ba = (uint16_t)(bits / 8 * ch);
    fwrite(&pcm, 2, 1, f); fwrite(&ch, 2, 1, f); fwrite(&rate, 4, 1, f);
    fwrite(&byte_rate, 4, 1, f); fwrite(&ba, 2, 1, f); fwrite(&bits, 2, 1, f);
    fwrite("data", 1, 4, f); fwrite(&data_bytes, 4, 1, f);
}

/* Sequence export for video assembly: one PNG per frame (frame_000000.png
 * ...) plus a WAV of the whole run.  Uses write_png so the frames come from
 * exactly the same core as the interactive build. */
int export_video(const char *rom, const char *bios, const char *outdir,
                 int frames) {
    GBA *g = calloc(1, sizeof(GBA));
    if (!g) return 1;
    gba_init(g);
    if (bios) gba_load_bios(g, bios);
    g->bios_enabled = bios ? 1 : 0;
    g->bios_fastboot = bios ? 0 : 1;
    if (!gba_load_rom(g, rom)) { fprintf(stderr, "export: cannot load %s\n", rom); free(g); return 1; }
    gba_reset(g);

    char path[1024];
    snprintf(path, sizeof path, "%s/audio.wav", outdir);
    FILE *wav = fopen(path, "wb");
    uint32_t wav_bytes = 0;
    if (wav) wav_header(wav, 0);

    for (int f = 1; f <= frames; f++) {
        gba_run_frame(g);
        snprintf(path, sizeof path, "%s/frame_%06d.png", outdir, f - 1);
        write_png(path, g->ppu.frame);
        if (wav) {
            int16_t buf[4096];
            int n;
            while ((n = apu_drain(buf, 2048)) > 0) {
                fwrite(buf, sizeof(int16_t) * 2, (size_t)n, wav);
                wav_bytes += (uint32_t)n * 4;
            }
        }
    }
    if (wav) {
        if (fseek(wav, 0, SEEK_SET) == 0) wav_header(wav, wav_bytes);
        fclose(wav);
    }
    fprintf(stderr, "export_video: %d frames, %u bytes PCM\n", frames, wav_bytes);
    free(g);
    return 0;
}

int export_run(const char *rom, const char *bios, const char *outdir,
               int frames, const int *pngs, int npng, double wavsec) {
    GBA *g = calloc(1, sizeof(GBA));
    if (!g) return 1;
    gba_init(g);
    if (bios) gba_load_bios(g, bios);
    g->bios_enabled = bios ? 1 : 0;
    g->bios_fastboot = bios ? 0 : 1;   /* no dump -> HLE boot, same as the app */
    if (!gba_load_rom(g, rom)) { fprintf(stderr, "export: cannot load %s\n", rom); free(g); return 1; }
    gba_reset(g);

    char path[1024];
    FILE *wav = NULL;
    uint32_t wav_bytes = 0;
    long wav_target = (long)(wavsec * SAMPLE_RATE);   /* frames (stereo pairs) */

    if (wavsec > 0) {
        snprintf(path, sizeof path, "%s/audio.wav", outdir);
        wav = fopen(path, "wb");
        if (wav) wav_header(wav, 0);                   /* patched at the end */
    }

    for (int f = 1; f <= frames; f++) {
        gba_run_frame(g);
        for (int i = 0; i < npng; i++) {
            if (pngs[i] == f) {
                snprintf(path, sizeof path, "%s/frame_%03d.png", outdir, f);
                write_png(path, g->ppu.frame);
                printf("export: wrote %s\n", path);
            }
        }
        if (wav) {
            int16_t buf[4096];
            int n;
            while ((n = apu_drain(buf, 2048)) > 0) {
                if (wav_bytes / 4 >= (uint32_t)wav_target) continue;   /* already full */
                long room = wav_target - (long)(wav_bytes / 4);
                if (n > room) n = (int)room;
                if (n <= 0) break;
                fwrite(buf, sizeof(int16_t) * 2, (size_t)n, wav);
                wav_bytes += (uint32_t)n * 4;
            }
        }
    }

    if (wav) {
        if (fseek(wav, 0, SEEK_SET) == 0) wav_header(wav, wav_bytes);
        fclose(wav);
        printf("export: wrote %s (%u bytes PCM, %.2f s)\n", "audio.wav", wav_bytes, (double)(wav_bytes / 4) / SAMPLE_RATE);
    }
    free(g);
    return 0;
}
